"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  ArrowRight,
  ArrowLeft,
  CheckCircle2,
  Sparkles,
  Building2,
  Users,
  AlertTriangle,
  Send,
  Shield,
  Calendar,
  MessageSquare,
} from "lucide-react";
import confetti from "canvas-confetti";
import { cn } from "@/lib/utils";

export default function DiagnosticForm() {
  const [step, setStep] = useState<number>(1);
  const [formData, setFormData] = useState({
    companyType: "PyME / Despacho Profesional",
    teamSize: "5 - 20 personas",
    primaryBottleneck: "Fuga de leads fuera de horario y citas no atendidas",
    currentTools: "WhatsApp + Correo electrónico + Hojas de cálculo",
    fullName: "",
    email: "",
    phone: "",
    notes: "",
  });
  const [isSubmitting, setIsSubmitting] = useState<boolean>(false);
  const [isSubmitted, setIsSubmitted] = useState<boolean>(false);

  const handleNext = () => {
    setStep((prev) => Math.min(prev + 1, 4));
  };

  const handleBack = () => {
    setStep((prev) => Math.max(prev - 1, 1));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setTimeout(() => {
      setIsSubmitting(false);
      setIsSubmitted(true);
      try {
        confetti({
          particleCount: 100,
          spread: 80,
          origin: { y: 0.6 },
        });
      } catch (err) {
        // Confetti fallback
      }
    }, 700);
  };

  return (
    <section id="diagnostico" className="relative py-24 sm:py-32 bg-[#02050e] border-t border-slate-800">
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Section Header */}
        <div className="text-center max-w-3xl mx-auto mb-16">
          <span className="brand-label text-blue-400">
            07 — DIAGNÓSTICO OPERATIVO & CONTACTO
          </span>
          <h2 className="font-brand-display text-3xl sm:text-5xl lg:text-6xl text-white font-light mt-3 leading-tight">
            Descubre en 2 minutos dónde se fuga tu{" "}
            <span className="italic text-blue-500 font-normal">rentabilidad operativa</span>
          </h2>
          <p className="text-slate-400 text-sm sm:text-base font-light mt-4 leading-relaxed">
            Completa la evaluación técnica para recibir un mapa personalizado de automatización
            agéntica y agendar una sesión estratégica con nuestros ingenieros.
          </p>
        </div>

        {/* Multi-Step Card Form */}
        <div className="rounded-3xl bg-slate-900/60 border border-slate-800 backdrop-blur-xl p-6 sm:p-10 lg:p-12 shadow-2xl relative">
          {!isSubmitted ? (
            <div>
              {/* Progress Steps Header */}
              <div className="flex items-center justify-between mb-8 pb-4 border-b border-slate-800">
                <div className="flex items-center gap-3">
                  <span className="w-8 h-8 rounded-full bg-blue-600/30 border border-blue-500/50 flex items-center justify-center font-mono text-xs text-blue-400 font-bold">
                    0{step}
                  </span>
                  <div>
                    <span className="text-xs font-mono text-slate-400 block">
                      PASO {step} DE 4
                    </span>
                    <span className="text-xs font-semibold text-slate-200">
                      {step === 1 && "Perfil de tu Empresa"}
                      {step === 2 && "Principal Cuello de Botella"}
                      {step === 3 && "Ecosistema Actual"}
                      {step === 4 && "Información de Contacto"}
                    </span>
                  </div>
                </div>

                <div className="hidden sm:flex items-center gap-1.5">
                  {[1, 2, 3, 4].map((s) => (
                    <div
                      key={s}
                      className={cn(
                        "h-1.5 rounded-full transition-all duration-300",
                        s === step
                          ? "w-8 bg-blue-500"
                          : s < step
                          ? "w-4 bg-emerald-500"
                          : "w-4 bg-slate-800"
                      )}
                    />
                  ))}
                </div>
              </div>

              {/* Form Steps */}
              <AnimatePresence mode="wait">
                {step === 1 && (
                  <motion.div
                    key="step1"
                    initial={{ opacity: 0, x: 10 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: -10 }}
                    className="space-y-6"
                  >
                    <div>
                      <label className="text-sm font-semibold text-white block mb-3">
                        ¿Qué tipo de organización o negocio operas?
                      </label>
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                        {[
                          "PyME / Despacho Profesional",
                          "Clínica Médica / Dental / Estética",
                          "Planta de Manufactura / Industria",
                          "Empresa Tecnológica / B2B SaaS",
                          "Servicios Financieros / Legal",
                          "Otra actividad corporativa",
                        ].map((opt) => (
                          <button
                            key={opt}
                            type="button"
                            onClick={() => setFormData({ ...formData, companyType: opt })}
                            className={cn(
                              "p-3.5 rounded-xl border text-left text-xs sm:text-sm transition-all cursor-pointer",
                              formData.companyType === opt
                                ? "bg-blue-600/20 border-blue-500 text-white shadow-glow-sm"
                                : "bg-slate-950/70 border-slate-800 text-slate-300 hover:border-slate-700"
                            )}
                          >
                            {opt}
                          </button>
                        ))}
                      </div>
                    </div>

                    <div className="pt-2">
                      <label className="text-sm font-semibold text-white block mb-3">
                        Tamaño aproximado del equipo operativo
                      </label>
                      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                        {["1 - 5 personas", "6 - 20 personas", "21 - 80 personas", "+80 personas"].map(
                          (opt) => (
                            <button
                              key={opt}
                              type="button"
                              onClick={() => setFormData({ ...formData, teamSize: opt })}
                              className={cn(
                                "p-3 rounded-xl border text-center text-xs font-mono transition-all cursor-pointer",
                                formData.teamSize === opt
                                  ? "bg-blue-600/20 border-blue-500 text-blue-300"
                                  : "bg-slate-950/70 border-slate-800 text-slate-400 hover:border-slate-700"
                              )}
                            >
                              {opt}
                            </button>
                          )
                        )}
                      </div>
                    </div>
                  </motion.div>
                )}

                {step === 2 && (
                  <motion.div
                    key="step2"
                    initial={{ opacity: 0, x: 10 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: -10 }}
                    className="space-y-6"
                  >
                    <div>
                      <label className="text-sm font-semibold text-white block mb-3">
                        ¿Cuál es el cuello de botella que más limita tu crecimiento actualmente?
                      </label>
                      <div className="grid grid-cols-1 gap-3">
                        {[
                          "Fuga de leads fuera de horario y citas no atendidas (No-Show)",
                          "Personal saturado copiando datos entre hojas de cálculo y emails",
                          "Procesos lentos de validación documental o cumplimiento normativo",
                          "Deuda tecnológica y falta de automatización entre nuestro ERP y CRM",
                          "Alto costo de contratación para poder atender a más clientes",
                        ].map((opt) => (
                          <button
                            key={opt}
                            type="button"
                            onClick={() => setFormData({ ...formData, primaryBottleneck: opt })}
                            className={cn(
                              "p-4 rounded-xl border text-left text-xs sm:text-sm transition-all cursor-pointer flex items-center justify-between",
                              formData.primaryBottleneck === opt
                                ? "bg-blue-600/20 border-blue-500 text-white shadow-glow-sm"
                                : "bg-slate-950/70 border-slate-800 text-slate-300 hover:border-slate-700"
                            )}
                          >
                            <span>{opt}</span>
                            {formData.primaryBottleneck === opt && (
                              <CheckCircle2 className="w-4 h-4 text-blue-400 shrink-0 ml-2" />
                            )}
                          </button>
                        ))}
                      </div>
                    </div>
                  </motion.div>
                )}

                {step === 3 && (
                  <motion.div
                    key="step3"
                    initial={{ opacity: 0, x: 10 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: -10 }}
                    className="space-y-6"
                  >
                    <div>
                      <label className="text-sm font-semibold text-white block mb-3">
                        ¿Qué herramientas forman el núcleo de tu operativa hoy?
                      </label>
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                        {[
                          "WhatsApp + Correo electrónico + Hojas de cálculo",
                          "CRM estructurado (HubSpot / Salesforce / Zoho)",
                          "ERP corporativo (SAP / Sage / Odoo / Software a medida)",
                          "Herramientas no-code previas (Make / Zapier / n8n básico)",
                        ].map((opt) => (
                          <button
                            key={opt}
                            type="button"
                            onClick={() => setFormData({ ...formData, currentTools: opt })}
                            className={cn(
                              "p-4 rounded-xl border text-left text-xs sm:text-sm transition-all cursor-pointer",
                              formData.currentTools === opt
                                ? "bg-blue-600/20 border-blue-500 text-white shadow-glow-sm"
                                : "bg-slate-950/70 border-slate-800 text-slate-300 hover:border-slate-700"
                            )}
                          >
                            {opt}
                          </button>
                        ))}
                      </div>
                    </div>
                  </motion.div>
                )}

                {step === 4 && (
                  <motion.div
                    key="step4"
                    initial={{ opacity: 0, x: 10 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: -10 }}
                    className="space-y-4"
                  >
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div>
                        <label className="text-xs text-slate-300 block mb-1.5 font-medium">
                          Nombre y Apellidos *
                        </label>
                        <input
                          type="text"
                          required
                          placeholder="Ej. Carlos Mendoza"
                          value={formData.fullName}
                          onChange={(e) => setFormData({ ...formData, fullName: e.target.value })}
                          className="w-full px-4 py-3 rounded-xl bg-slate-950 border border-slate-800 text-white text-sm focus:outline-none focus:border-blue-500"
                        />
                      </div>

                      <div>
                        <label className="text-xs text-slate-300 block mb-1.5 font-medium">
                          Correo Corporativo *
                        </label>
                        <input
                          type="email"
                          required
                          placeholder="carlos@tuempresa.com"
                          value={formData.email}
                          onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                          className="w-full px-4 py-3 rounded-xl bg-slate-950 border border-slate-800 text-white text-sm focus:outline-none focus:border-blue-500"
                        />
                      </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div>
                        <label className="text-xs text-slate-300 block mb-1.5 font-medium">
                          Teléfono / WhatsApp de Contacto
                        </label>
                        <input
                          type="tel"
                          placeholder="+34 600 000 000"
                          value={formData.phone}
                          onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                          className="w-full px-4 py-3 rounded-xl bg-slate-950 border border-slate-800 text-white text-sm focus:outline-none focus:border-blue-500"
                        />
                      </div>

                      <div>
                        <label className="text-xs text-slate-300 block mb-1.5 font-medium">
                          Detalle o reto específico (opcional)
                        </label>
                        <input
                          type="text"
                          placeholder="Ej. Queremos automatizar la confirmación de citas"
                          value={formData.notes}
                          onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                          className="w-full px-4 py-3 rounded-xl bg-slate-950 border border-slate-800 text-white text-sm focus:outline-none focus:border-blue-500"
                        />
                      </div>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>

              {/* Navigation Buttons */}
              <div className="flex items-center justify-between pt-8 mt-6 border-t border-slate-800">
                {step > 1 ? (
                  <button
                    type="button"
                    onClick={handleBack}
                    className="inline-flex items-center gap-2 px-4 py-2.5 rounded-xl bg-slate-950 text-slate-300 hover:text-white border border-slate-800 text-xs font-medium cursor-pointer"
                  >
                    <ArrowLeft className="w-3.5 h-3.5" />
                    <span>Atrás</span>
                  </button>
                ) : (
                  <div />
                )}

                {step < 4 ? (
                  <button
                    type="button"
                    onClick={handleNext}
                    className="inline-flex items-center gap-2 px-6 py-3 rounded-xl bg-blue-600 hover:bg-blue-500 text-white text-xs sm:text-sm font-semibold shadow-glow-sm cursor-pointer"
                  >
                    <span>Siguiente Paso</span>
                    <ArrowRight className="w-4 h-4" />
                  </button>
                ) : (
                  <button
                    type="button"
                    onClick={handleSubmit}
                    disabled={isSubmitting || !formData.fullName || !formData.email}
                    className="inline-flex items-center gap-2 px-7 py-3 rounded-xl bg-blue-600 hover:bg-blue-500 text-white text-xs sm:text-sm font-semibold shadow-glow-md disabled:opacity-50 cursor-pointer"
                  >
                    {isSubmitting ? (
                      <span>Analizando diagnóstico...</span>
                    ) : (
                      <>
                        <span>Enviar y Solicitar Diagnóstico</span>
                        <Send className="w-4 h-4" />
                      </>
                    )}
                  </button>
                )}
              </div>
            </div>
          ) : (
            /* Submission Success State */
            <div className="text-center py-8 space-y-6">
              <div className="w-16 h-16 rounded-full bg-emerald-500/20 border border-emerald-500/40 flex items-center justify-center text-emerald-400 mx-auto">
                <CheckCircle2 className="w-9 h-9" />
              </div>

              <div className="max-w-md mx-auto space-y-2">
                <span className="brand-label text-blue-400 text-xs">
                  DIAGNÓSTICO REGISTRADO CON ÉXITO
                </span>
                <h3 className="font-brand-display text-3xl text-white">
                  ¡Gracias, {formData.fullName}!
                </h3>
                <p className="text-xs sm:text-sm text-slate-300 leading-relaxed font-light">
                  Nuestro equipo de ingeniería y estrategia ha recibido los detalles de tu empresa (
                  <strong className="text-blue-400">{formData.companyType}</strong>). En menos de 24
                  horas te contactaremos con una propuesta preliminar de arquitectura de agentes.
                </p>
              </div>

              <div className="p-4 rounded-2xl bg-slate-950 border border-slate-800 max-w-sm mx-auto text-left font-mono text-[11px] space-y-1 text-slate-300">
                <div>
                  <span className="text-slate-400">Cuello de Botella:</span> {formData.primaryBottleneck}
                </div>
                <div>
                  <span className="text-slate-400">Equipo:</span> {formData.teamSize}
                </div>
                <div>
                  <span className="text-slate-400">Canal de Contacto:</span> {formData.email}
                </div>
              </div>

              <button
                type="button"
                onClick={() => {
                  setIsSubmitted(false);
                  setStep(1);
                }}
                className="px-6 py-2.5 rounded-xl bg-slate-900 hover:bg-slate-800 text-slate-300 text-xs font-mono border border-slate-800"
              >
                Realizar otra consulta
              </button>
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  Cpu,
  Database,
  ShieldCheck,
  Zap,
  Play,
  CheckCircle2,
  Terminal,
  MessageSquare,
  FileCheck,
  RefreshCw,
  GitBranch,
  Layers,
  Activity,
} from "lucide-react";
import { cn } from "@/lib/utils";

interface AgentNode {
  id: string;
  name: string;
  category: string;
  status: "idle" | "processing" | "success";
  icon: React.ElementType;
  description: string;
  tech: string;
  outputPreview: string;
  metrics: { label: string; val: string };
}

const NODES_DATA: AgentNode[] = [
  {
    id: "ingestion",
    name: "01. Ingestión Multi-Canal",
    category: "Data Ingestion Layer",
    status: "success",
    icon: MessageSquare,
    description: "Captura de leads, emails, mensajes de WhatsApp y webhooks en tiempo real 24/7.",
    tech: "WhatsApp Cloud API · Webhooks · IMAP",
    outputPreview: '{"source":"whatsapp_lead","payload":{"msg":"Requiero auditoría de procesos IA urgente","urgency":"high"}}',
    metrics: { label: "Latencia Ingesta", val: "18ms" },
  },
  {
    id: "reasoning",
    name: "02. Motor Cognitivo SyntIQ",
    category: "Reasoning & Agent Architecture",
    status: "processing",
    icon: Cpu,
    description: "Razonamiento contextual profundo, clasificación semántica y asignación de flujo de trabajo.",
    tech: "Claude 3.5 Sonnet · LangChain · RAG",
    outputPreview: '{"classification":"B2B_Enterprise_Audit","intent":"Schedule_Diagnostic","score":0.98,"suggested_route":"Agent_Consultant_Alam"}',
    metrics: { label: "Precisión Semántica", val: "99.4%" },
  },
  {
    id: "governance",
    name: "03. Capa de Gobernanza Legal",
    category: "Compliance & Security Shield",
    status: "success",
    icon: ShieldCheck,
    description: "Validación estricta 'Human-in-the-Loop', anonimización de datos y cumplimiento regulatorio.",
    tech: "Audit Logs · ISO 13485 · OMA Standards",
    outputPreview: '{"compliance_check":"PASSED","pii_redacted":true,"hallucination_index":0.00,"governance_officer":"Laura_Espino"}',
    metrics: { label: "Índice Alucinación", val: "0.00%" },
  },
  {
    id: "orchestration",
    name: "04. Orquestador Transaccional",
    category: "Workflow Engine",
    status: "idle",
    icon: Layers,
    description: "Sincronización bidireccional inmediata con CRM, ERP y bases de datos corporativas.",
    tech: "n8n Self-Hosted · PostgreSQL · REST APIs",
    outputPreview: '{"db_sync":"COMPLETED","crm_deal_id":"DEAL-84920","erp_updated":true,"node_executions":14}',
    metrics: { label: "Uptime de Nodos", val: "99.98%" },
  },
  {
    id: "execution",
    name: "05. Despacho & Ejecución 24/7",
    category: "Autonomous Delivery",
    status: "idle",
    icon: Zap,
    description: "Ejecución final sin intervención manual: respuesta instantánea, cita agendada y reporte generado.",
    tech: "Auto-Dispatch · Calendar Sync · Webhooks",
    outputPreview: '{"status":"RESOLVED","action":"Calendar_Invite_Sent","lead_nurtured":true,"revenue_leakage_prevented":"$4,200 USD"}',
    metrics: { label: "Tiempo Ciclo Total", val: "280ms" },
  },
];

export default function AgentOrchestratorVisual() {
  const [activeNodeId, setActiveNodeId] = useState<string>("reasoning");
  const [isSimulating, setIsSimulating] = useState<boolean>(false);
  const [simulationStep, setSimulationStep] = useState<number>(1);
  const [logs, setLogs] = useState<string[]>([
    "00:00:01 [INIT] SyntIQ Multi-Agent Orchestrator Engine v2.4 initialized.",
    "00:00:02 [READY] 5 autonomous agent pipelines listening on cluster.",
  ]);

  const activeNode = NODES_DATA.find((n) => n.id === activeNodeId) || NODES_DATA[1];

  const runSimulation = () => {
    if (isSimulating) return;
    setIsSimulating(true);
    setSimulationStep(0);
    setLogs((prev) => [
      ...prev,
      `[SIM] Iniciando simulación de ciclo operativo completo...`,
    ]);

    const nodeIds = ["ingestion", "reasoning", "governance", "orchestration", "execution"];
    nodeIds.forEach((id, idx) => {
      setTimeout(() => {
        setActiveNodeId(id);
        setSimulationStep(idx);
        setLogs((prev) => [
          ...prev.slice(-4),
          `[STEP 0${idx + 1}] Nódulo '${id}' procesado con éxito en ${20 + idx * 15}ms.`,
        ]);
        if (idx === nodeIds.length - 1) {
          setTimeout(() => {
            setIsSimulating(false);
            setLogs((prev) => [
              ...prev.slice(-4),
              `[SUCCESS] Ciclo completado. 0% fricción humana, 100% trazabilidad.`,
            ]);
          }, 600);
        }
      }, (idx + 1) * 700);
    });
  };

  return (
    <div className="relative w-full rounded-2xl bg-[#090d16]/90 border border-slate-800/80 backdrop-blur-xl shadow-2xl overflow-hidden">
      {/* Top Console Bar */}
      <div className="flex items-center justify-between px-4 py-3 bg-slate-950/80 border-b border-slate-800 text-xs">
        <div className="flex items-center gap-2">
          <div className="flex gap-1.5">
            <span className="w-2.5 h-2.5 rounded-full bg-red-500/80"></span>
            <span className="w-2.5 h-2.5 rounded-full bg-amber-500/80"></span>
            <span className="w-2.5 h-2.5 rounded-full bg-emerald-500/80"></span>
          </div>
          <span className="ml-2 font-mono text-[11px] text-slate-400">
            syntiq-orchestrator://cluster-prod-01
          </span>
        </div>

        <div className="flex items-center gap-3">
          <button
            type="button"
            onClick={runSimulation}
            disabled={isSimulating}
            className={cn(
              "flex items-center gap-1.5 px-3 py-1 rounded-md text-[11px] font-medium transition-all",
              isSimulating
                ? "bg-blue-900/50 text-blue-300 border border-blue-700/50 cursor-not-allowed"
                : "bg-blue-600 hover:bg-blue-500 text-white shadow-glow-sm cursor-pointer"
            )}
          >
            {isSimulating ? (
              <>
                <RefreshCw className="w-3 h-3 animate-spin" />
                <span>Ejecutando Pipeline...</span>
              </>
            ) : (
              <>
                <Play className="w-3 h-3 fill-white" />
                <span>Simular Ciclo Operativo</span>
              </>
            )}
          </button>
        </div>
      </div>

      {/* Main Orchestrator Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-0">
        {/* Left: Interactive Nodes Visual Flow (7 cols) */}
        <div className="lg:col-span-7 p-4 sm:p-6 border-b lg:border-b-0 lg:border-r border-slate-800/80 bg-grid-pattern relative">
          <div className="flex items-center justify-between mb-4">
            <span className="brand-label text-blue-400 flex items-center gap-1.5">
              <GitBranch className="w-3.5 h-3.5" /> Pipeline de Agentes Autónomos
            </span>
            <span className="text-[11px] font-mono text-slate-400">
              {simulationStep + 1}/5 Nódulos Activos
            </span>
          </div>

          {/* Connected Flow List */}
          <div className="space-y-3">
            {NODES_DATA.map((node, index) => {
              const Icon = node.icon;
              const isCurrent = node.id === activeNodeId;
              const isPast = isSimulating && simulationStep >= index;

              return (
                <div key={node.id} className="relative">
                  {/* Vertical Connection Line */}
                  {index < NODES_DATA.length - 1 && (
                    <div className="absolute left-5 top-10 bottom-[-14px] w-[2px] bg-slate-800 z-0">
                      {(isCurrent || isPast) && (
                        <div className="w-full h-full bg-gradient-to-b from-blue-500 to-transparent animate-pulse" />
                      )}
                    </div>
                  )}

                  <button
                    type="button"
                    onClick={() => setActiveNodeId(node.id)}
                    className={cn(
                      "relative z-10 w-full flex items-center justify-between p-3 rounded-xl transition-all duration-300 text-left cursor-pointer",
